"  const handleToggleItemMgmtAvailability = async (item) => {
    if (getStaffPermissions()?.pos_access?.OperationManagement?.ItemsManagement?.item_enabled_disabled === false) {
      toast.error("You do not have permission to enable/disable items.");
      return;
    }
    const nextAvailability = !item.availability;
    try {
      if (navigator.onLine && !String(item.id).startsWith('L-')) {
        await posService.updateMenuItem(item.id, { availability: nextAvailability });
      }

      setItemMgmtItems(prev => {
        const nextItems = prev.map(i => {
          if (i.id === item.id) {
            return {
              ...i,
              availability: nextAvailability,
              synced: navigator.onLine && !String(item.id).startsWith('L-') ? i.synced : false
            };
          }
          return i;
        });
        localStorage.setItem('pos_item_mgmt_items', JSON.stringify(nextItems));
        return nextItems;
      });

      if (!navigator.onLine) {
        // Optimistic update to billing catalog
        setCatalog(prev => {
          const nextCatalog = prev.map(c => c.id === item.id ? { ...c, is_active: nextAvailability } : c);
          localStorage.setItem('pos_catalog_cache', JSON.stringify(nextCatalog));
          return nextCatalog;
        });
        toast.error("Offline Mode: Availability updated locally");
      } else {
        await refreshBillingCatalog();
        try {
           const ogRes = await posService.getOptionGroups();
           setOptionGroups(ogRes.data || []);
        } catch (err) {
           console.error("Failed to refresh option groups:", err);
        }
        toast.success(`"${item.product_name}" availability updated`);
      }
    } catch (err) {
      console.error('Failed to update availability:', err);
      toast.error('Failed to update availability');
    }
  };"
